import { chromium } from 'playwright';

\(async \(\) => {
  console.log\('🧪 测试 6h 不同场景...\\n'\);

  const browser = await chromium.launch\({ headless: false }\);
  const page = await browser.newPage\(\);

  // 收集详细日志
  page.on\('console', msg => {
    const text = msg.text\(\);
    if \(text.includes\('ResourceChart'\) || text.includes\('reference'\) || text.includes\('dataAge'\)\) {
      console.log\(`[Browser] ${text}`\);
    }
  }\);

  await page.goto\('http://localhost:3003/monitor'\);
  console.log\('⏳ 等待页面加载...'\);
  await page.waitForTimeout\(8000\);

  // 获取当前历史数据信息
  const historyInfo = await page.evaluate\(\(\) => {
    return new Promise\(\(resolve\) => {
      fetch\('/api/monitor/history?minutes=60'\)
        .then\(r => r.json\(\)\)
        .then\(data => {
          if \(data.history && data.history.length > 0\) {
            const now = Date.now\(\);
            const timestamps = data.history.map\(h => new Date\(h.timestamp\).getTime\(\)\);
            const latest = Math.max\(...timestamps\);
            const oldest = Math.min\(...timestamps\);

            resolve\({
              count: data.history.length,
              now: new Date\(now\).toISOString\(\),
              latest: new Date\(latest\).toISOString\(\),
              oldest: new Date\(oldest\).toISOString\(\),
              dataAge: Math.round\(\(now - latest\) / 60000\),
              span: Math.round\(\(latest - oldest\) / 60000\),
            }\);
          } else {
            resolve\({ error: 'No history' }\);
          }
        }\);
    }\);
  }\);

  console.log\('\\n📊 历史数据信息:'\);
  console.log\(`  数据点数量: ${historyInfo.count}`\);
  console.log\(`  当前时间: ${historyInfo.now}`\);
  console.log\(`  最新数据: ${historyInfo.latest}`\);
  console.log\(`  最旧数据: ${historyInfo.oldest}`\);
  console.log\(`  数据年龄: ${historyInfo.dataAge} 分钟`\);
  console.log\(`  时间跨度: ${historyInfo.span} 分钟`\);

  console.log\('\\n🔍 测试 6h 按钮...'\);
  await page.click\('button:has-text\("6h"\)'\);
  await page.waitForTimeout\(3000\);

  console.log\('\\n⏸️  保持浏览器打开10秒...'\);
  await page.waitForTimeout\(10000\);

  await browser.close\(\);
  console.log\('\\n✅ 测试完成！'\);
}\)\(\);
EOF)

